const MAX_ITEMS: usize = 32;
const Node = struct { data: u16 = 0, idx: i32 = 0, next: i32 = -1 };
fn crcByte(value_in: u16, crc_in: u16) u16 { var value=value_in;var crc=crc_in;for(0..8)|_|{const mix=(value&1)^(crc&1);value>>=1;if(mix!=0)crc^=0x4002;crc>>=1;if(mix!=0)crc|=0x8000 else crc&=0x7fff;}return crc; }
fn crc16(value:u16,crc:u16)u16{return crcByte(value>>8,crcByte(value&255,crc));}
fn compare(a:*[MAX_ITEMS+2]Node,x:usize,y:usize,complex:bool,seed:u16)i32{if(complex){if(a[x].data&0x80==0)a[x].data=(a[x].data&0xff00)|0x80|((a[x].data^(a[x].data>>8)^seed)&0x7f);if(a[y].data&0x80==0)a[y].data=(a[y].data&0xff00)|0x80|((a[y].data^(a[y].data>>8)^seed)&0x7f);return @as(i32,a[x].data&127)-@as(i32,a[y].data&127);}a[x].data=(a[x].data&0xff00)|((a[x].data>>8)&255);a[y].data=(a[y].data&0xff00)|((a[y].data>>8)&255);return a[x].idx-a[y].idx;}
fn sortList(a:*[MAX_ITEMS+2]Node,head_in:i32,complex:bool,seed:u16)i32{var head=head_in;var width:i32=1;while(true){var p=head;var new_head:i32 = -1;var tail:i32 = -1;var merges:i32=0;while(p>=0){merges+=1;var q=p;var ps:i32=0;for(0..@intCast(width)) |_|{ps+=1;q=a[@intCast(q)].next;if(q<0)break;}var qs=width;while(ps>0 or (qs>0 and q>=0)){var e:i32=0;if(ps==0){e=q;q=a[@intCast(q)].next;qs-=1;}else if(qs==0 or q<0){e=p;p=a[@intCast(p)].next;ps-=1;}else if(compare(a,@intCast(p),@intCast(q),complex,seed)<=0){e=p;p=a[@intCast(p)].next;ps-=1;}else{e=q;q=a[@intCast(q)].next;qs-=1;}if(tail>=0)a[@intCast(tail)].next=e else new_head=e;tail=e;}p=q;}a[@intCast(tail)].next=-1;head=new_head;if(merges<=1)return head;width*=2;}}
fn findNode(a:*const [MAX_ITEMS+2]Node,head_in:i32,idx:i32,data:i32)i32{var p=head_in;while(p>=0){const node=a[@intCast(p)];if((idx>=0 and node.idx==idx) or (idx<0 and node.data&255==data))return p;p=node.next;}return -1;}
fn reverse(a:*[MAX_ITEMS+2]Node,head:*i32)void{var prev:i32 = -1;var cur=head.*;while(cur>=0){const u:@TypeOf(cur)=@intCast(cur);const next=a[u].next;a[u].next=prev;prev=cur;cur=next;}head.*=prev;}

export fn embedded_list_stress(input:[*c]const i64,length:usize,output:[*c]u8,capacity:usize)i64{
 if(input==null or length!=4)return -1;const rn=input[0];const seed=input[1];const find_count=input[2];const mode=input[3];if(rn<4 or rn>MAX_ITEMS or seed<1 or seed>255 or find_count<0 or find_count>32 or (mode != -1 and mode != 1))return -1;
 const n:usize=@intCast(rn);const tail=n+1;var a:[MAX_ITEMS+2]Node=@splat(.{});a[0]=.{.data=0x8080,.idx=0,.next=1};a[tail]=.{.data=0xffff,.idx=0x7fff,.next=-1};for(0..n)|i|{const dat:u16=@intCast(((@as(usize,@intCast(seed))^i)&15)<<3|(i&7));a[i+1]=.{.data=(dat<<8)|dat,.idx=0,.next=@intCast(i+2)};}a[n].next=@intCast(tail);
 var ix:i32=1;var p=a[0].next;while(p!=@as(i32,@intCast(tail))){const u:usize=@intCast(p);if(ix<@as(i32,@intCast(n/5))){a[u].idx=ix;ix+=1;}else{const pat=ix^@as(i32,@intCast(seed));ix+=1;a[u].idx=(((ix&7)<<8)|pat)&0x3fff;}p=a[u].next;}var head=sortList(&a,0,false,@intCast(seed));
 var info_idx:i32=@intCast(mode);var info_data:i32=0;var result:u16=0;var found:u32=0;var missed:u32=0;for(0..@intCast(find_count))|k|{info_data=@intCast(k&255);const got=findNode(&a,head,info_idx,info_data);reverse(&a,&head);if(got<0){missed+=1;const first=a[@intCast(head)].next;if(first>=0)result+%=((a[@intCast(first)].data>>8)&1);}else{found+=1;const g:usize=@intCast(got);if(a[g].data&1!=0)result+%=((a[g].data>>9)&1);const next=a[g].next;if(next>=0){a[g].next=a[@intCast(next)].next;a[@intCast(next)].next=a[@intCast(head)].next;a[@intCast(head)].next=next;}}if(info_idx>=0)info_idx+=1;}
 result+%= @truncate((found*%4)-%missed);if(mode>0)head=sortList(&a,head,true,@intCast(seed));const at=a[@intCast(head)].next;if(at>=0){const x:usize=@intCast(at);const rem:usize=@intCast(a[x].next);const td=a[x].data;a[x].data=a[rem].data;a[rem].data=td;const ti=a[x].idx;a[x].idx=a[rem].idx;a[rem].idx=ti;a[x].next=a[rem].next;a[rem].next=-1;var f=findNode(&a,head,info_idx,info_data);if(f<0)f=a[@intCast(head)].next;while(f>=0){result=crc16(a[@intCast(head)].data,result);f=a[@intCast(f)].next;}const td2=a[rem].data;a[rem].data=a[x].data;a[x].data=td2;const ti2=a[rem].idx;a[rem].idx=a[x].idx;a[x].idx=ti2;a[rem].next=a[x].next;a[x].next=@intCast(rem);}
 head=sortList(&a,head,false,@intCast(seed));var f=a[@intCast(head)].next;while(f>=0){result=crc16(a[@intCast(head)].data,result);f=a[@intCast(f)].next;}if(output==null or capacity<2)return -2;output[0]=@truncate(result);output[1]=@truncate(result>>8);return 2;
}
